            [ROOT_ATTRIBUTE]: '',
            [READY_ATTRIBUTE]: ready.value ? '' : undefined,
            [SETTLING_ATTRIBUTE]: settling.value ? '' : undefined,
            ref: (component: unknown) => {
              root.value = elementOf(component);
            },
          },
          {
            default: (slotProps: Record<string, unknown>) => [
              render(),
              slots.default?.(slotProps),
            ],
          },
        ),
      );
